import {
  Component,
  ComponentInterface,
  Element,
  Event,
  EventEmitter,
  h,
  Host,
  Listen,
  Prop,
  Watch,
} from '@stencil/core';
import { NavigationSizes } from '../../../../types';
import { AriaAttributes, extractAriaAttributes } from '../../../../utils/a11y-helper';
import { NavigationUtilities } from '../shared/navigation-utilities';

type BurgerMenuItemElement = HTMLGroupuiBurgerMenuItemElement | HTMLGroupuiBurgerMenuUtilityItemElement;

/**
 * @slot default - default slot for the content of the burger-menu component (usually groupui-burger-menu-items)
 */
@Component({
  tag: 'groupui-burger-menu',
  styleUrl: 'burger-menu.scss',
  shadow: true,
})
export class BurgerMenu implements ComponentInterface {
  /**
   * toggles the menu
   */
  @Prop({ reflect: true, mutable: true }) open: boolean = false;

  /**
   * sets the side-navigation size
   */
  @Prop({ reflect: true }) readonly size: NavigationSizes = 's';

  /**
   * disables the slide animation
   */
  @Prop({ reflect: true }) readonly noAnimation: boolean = false;

  /**
   * activates the dividers
   */
  @Prop({ reflect: true }) readonly divider: boolean;

  /**
   * moves the chevrons to the left side
   */
  @Prop({ reflect: true }) readonly treeLayout: boolean;

  /**
   * @internal
   * Deactivates the active state management.
   */
  @Prop({ reflect: true }) readonly manualMode: boolean = false;

  /**
   * ARIA label for the open button.
   */
  @Prop({ reflect: true, attribute: 'a11y-label-open-button' }) readonly a11yLabelOpenButton: string =
    'Open hamburger menu';

  /**
   * ARIA label for the close button.
   */
  @Prop({ reflect: true, attribute: 'a11y-label-close-button' }) readonly a11yLabelCloseButton: string =
    'Close hamburger menu';

  /**
   * Emitted when the component has loaded.
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  /**
   * Emitted when the active item changes
   */
  @Event({ bubbles: false }) groupuiChange: EventEmitter<void>;

  @Element() host: HTMLElement;

  private ariaAttributes: AriaAttributes;

  private navigationUtilities = new NavigationUtilities<BurgerMenuItemElement>();

  componentWillLoad(): void {
    this.ariaAttributes = extractAriaAttributes(this.host);
    this.updateSizePropOfChild();
    this.updateDividerPropOfChild();
    this.updateTreeLayoutPropOfChild();
    this.onOpenChange();
  }

  @Watch('size')
  updateSizePropOfChild() {
    const items = [
      ...this.navigationUtilities.getAllItems(this.host, 'groupui-burger-menu-item, groupui-burger-menu-utility-item'),
      ...this.navigationUtilities.getAllItems(this.host, 'groupui-burger-menu-category'),
    ];
    this.navigationUtilities.setAttribute(items, 'size', this.size);
  }

  @Watch('divider')
  updateDividerPropOfChild() {
    const items = this.navigationUtilities.getAllItems(
      this.host,
      'groupui-burger-menu-item, groupui-burger-menu-utility-item'
    );
    this.navigationUtilities.updateBooleanAttribute(items, 'divider', this.divider);
  }

  @Watch('treeLayout')
  updateTreeLayoutPropOfChild() {
    const items = this.navigationUtilities.getAllItems(
      this.host,
      'groupui-burger-menu-item, groupui-burger-menu-utility-item'
    );
    this.navigationUtilities.updateBooleanAttribute(items, 'tree-layout', this.treeLayout);
  }

  @Watch('open')
  onOpenChange(): void {
    if (this.open) {
      this.enableKeyboardHandlingForItems();
    } else {
      this.disableKeyboardHandlingForItems();
    }
  }

  @Listen('click')
  handleClick(event: Event): void {
    const item =
      (event.target as HTMLElement).closest('groupui-burger-menu-item') ||
      (event.target as HTMLElement).closest('groupui-burger-menu-utility-item');

    if (!item || item.disabled || this.manualMode) {
      return;
    }

    if (this.navigationUtilities.isLeafItem(item, 'groupui-burger-menu-item')) {
      this.navigationUtilities.removeActiveFromAllItems(
        this.host,
        'groupui-burger-menu-item, groupui-burger-menu-utility-item'
      );
      this.navigationUtilities.setActiveItem(item);
      this.open = false;
      this.groupuiChange.emit();
      this.host.dispatchEvent(new globalThis.Event('change'));
      return;
    }

    if (this.navigationUtilities.hasActiveChildItems(item, 'groupui-burger-menu-item')) {
      item.hasAttribute('open')
        ? this.navigationUtilities.setActiveItem(item)
        : this.navigationUtilities.removeActiveItem(item);
    }

    this.navigationUtilities.toggleOpenState(item);
  }

  @Listen('keydown')
  handleKeyDown(event: KeyboardEvent): void {
    if (!this.open) return;
    if (event.key === 'Escape') {
      this.open = false;
      this.closeDrilldowns();
      this.host.shadowRoot.querySelector('button').focus();
    } else if (event.code === 'Tab') {
      this.handleTabOrder(event);
    } else if (event.code === 'ArrowUp' || event.code === 'ArrowDown') {
      this.preventScrolling(event);
    }
  }

  private preventScrolling(event: KeyboardEvent) {
    event.preventDefault();
    event.stopPropagation();
  }

  private handleTabOrder(event: KeyboardEvent) {
    const childOfClosedItem = 'groupui-burger-menu-item:not([open]) > groupui-burger-menu-item';
    const prevSiblingOfOpenDrilldown =
      'groupui-burger-menu-drilldown-item:has(~ groupui-burger-menu-drilldown-item[open])';
    const nextSiblingOfOpenDrilldown = 'groupui-burger-menu-drilldown-item[open] ~ groupui-burger-menu-drilldown-item';
    const parentOfOpenDrilldown =
      'groupui-burger-menu-drilldown-item[open]:has(> groupui-burger-menu-drilldown-item[open])';
    const childItemOfClosedDrilldown = 'groupui-burger-menu-drilldown-item:not([open]) > groupui-burger-menu-item';
    const childOfClosedDrilldown =
      'groupui-burger-menu-drilldown-item:not([open]) > groupui-burger-menu-drilldown-item';

    const hiddenItems = this.navigationUtilities.getAllItems(
      this.host,
      [
        childOfClosedItem,
        prevSiblingOfOpenDrilldown,
        nextSiblingOfOpenDrilldown,
        parentOfOpenDrilldown,
        childItemOfClosedDrilldown,
        childOfClosedDrilldown,
      ].join(',')
    );
    const visibleItems = this.navigationUtilities
      .getAllItems(
        this.host,
        ['groupui-burger-menu-item', 'groupui-burger-menu-utility-item', 'groupui-burger-menu-drilldown-item'].join(',')
      )
      .filter((item) => hiddenItems.indexOf(item) < 0)
      .filter((item) => !item.disabled);

    const isFirstOrLastItem = event.shiftKey ? visibleItems[0] : visibleItems.pop();
    if (event.target === isFirstOrLastItem) {
      event.preventDefault();
      event.stopPropagation();
      this.host.shadowRoot.querySelector('button').focus();
    }
  }

  private disableKeyboardHandlingForItems(): void {
    const items = this.navigationUtilities.getAllItems(
      this.host,
      'groupui-burger-menu-item, groupui-burger-menu-utility-item'
    );
    this.navigationUtilities.setAttribute(items, 'tabindex', '-1');
  }

  private enableKeyboardHandlingForItems(): void {
    const items = this.navigationUtilities.getAllItems(
      this.host,
      'groupui-burger-menu-item, groupui-burger-menu-utility-item'
    );
    this.navigationUtilities.removeAttribute(items, 'tabindex');
  }

  private closeDrilldowns() {
    Array.from(this.host.querySelectorAll('groupui-burger-menu-drilldown-item')).forEach((item) => {
      item.removeAttribute('open');
    });
  }

  private toggleOpen = () => {
    this.open = !this.open;
    if (!this.open) {
      this.closeDrilldowns();
    }
  };

  private iconName(): string {
    return this.open ? 'close-24' : 'menu-24';
  }

  private getButtonAriaLabel(): string {
    return this.open ? this.a11yLabelCloseButton : this.a11yLabelOpenButton;
  }

  render() {
    return (
      <Host role="listitem">
        <button tabIndex={0} onClick={this.toggleOpen} aria-label={this.getButtonAriaLabel()}>
          <groupui-icon name={this.iconName()}></groupui-icon>
        </button>
        <nav {...this.ariaAttributes}>
          <slot name="nav-items"></slot>
          <slot name="utilities"></slot>
        </nav>
      </Host>
    );
  }
}
